<?php
require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$errores=[];if($_SERVER['REQUEST_METHOD']==='POST'){$id_solicitud=(int)$_POST['id_solicitud'];$fecha=$_POST['fecha']??'';$hora=$_POST['hora']??'';$tipo=$_POST['tipo_cita']??'Recepción';$obs=trim($_POST['observaciones']??'');if(!$id_solicitud||!$fecha||!$hora)$errores[]='Completa solicitud, fecha y hora.';if(!$errores){$q=$pdo->prepare('SELECT id_cliente FROM solicitudes WHERE id_solicitud=?');$q->execute([$id_solicitud]);$cliente=$q->fetchColumn();if(!$cliente)$errores[]='Solicitud no encontrada.';else{$q=$pdo->prepare('INSERT INTO citas (id_solicitud,id_cliente,fecha,hora,tipo_cita,observaciones) VALUES (?,?,?,?,?,?)');$q->execute([$id_solicitud,$cliente,$fecha,$hora,$tipo,$obs]);establecer_mensaje('exito','Cita programada correctamente.');redirigir('citas.php');}}}$solicitudes=$pdo->query("SELECT s.id_solicitud,s.marca,s.modelo,u.nombre AS cliente FROM solicitudes s JOIN usuarios u ON u.id_usuario=s.id_cliente WHERE s.estado NOT IN ('Rechazada','Cancelada','Terminada') ORDER BY s.id_solicitud DESC")->fetchAll();$citas=$pdo->query('SELECT c.*,s.marca,s.modelo,u.nombre AS cliente FROM citas c JOIN solicitudes s ON s.id_solicitud=c.id_solicitud JOIN usuarios u ON u.id_usuario=c.id_cliente ORDER BY c.fecha,c.hora')->fetchAll();$titulo_pagina='Citas';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">AGENDA</span><h1>Citas del taller</h1><p>Programa recepciones, diagnósticos y entregas.</p></div></div><?php if($errores): ?><div class="alerta alerta-error"><?= escapar(implode(' ',$errores)) ?></div><?php endif; ?><section class="formulario-panel" style="margin-bottom:20px"><h2>Programar cita</h2><form method="post" class="formulario"><div class="rejilla-tres"><label>Solicitud<select name="id_solicitud" required><option value="">Selecciona...</option><?php foreach($solicitudes as $s): ?><option value="<?= $s['id_solicitud'] ?>">#<?= $s['id_solicitud'] ?> · <?= escapar($s['cliente'].' / '.$s['marca'].' '.$s['modelo']) ?></option><?php endforeach; ?></select></label><label>Fecha<input type="date" name="fecha" min="<?= date('Y-m-d') ?>" required></label><label>Hora<input type="time" name="hora" required></label><label>Tipo<select name="tipo_cita"><option>Recepción</option><option>Diagnóstico</option><option>Entrega</option></select></label><label>Observaciones<input name="observaciones"></label></div><button class="boton" type="submit">Guardar cita</button></form></section><section class="tabla-contenedor"><table class="tabla"><thead><tr><th>Fecha</th><th>Cliente</th><th>Consola</th><th>Tipo</th><th>Observaciones</th><th>Estado</th></tr></thead><tbody><?php foreach($citas as $c): ?><tr><td><?= date('d/m/Y H:i',strtotime($c['fecha'].' '.$c['hora'])) ?></td><td><?= escapar($c['cliente']) ?></td><td><?= escapar($c['marca'].' '.$c['modelo']) ?></td><td><?= escapar($c['tipo_cita']) ?></td><td><?= escapar($c['observaciones']) ?></td><td><span class="<?= estado_clase($c['estado']) ?>"><?= escapar($c['estado']) ?></span></td></tr><?php endforeach; ?></tbody></table></section><?php require_once __DIR__.'/../includes/pie.php'; ?>

